def memoize(func):
    cache = {}
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return wrapper

@memoize
def fib(n):
    if n < 2: return n
    return fib(n-1) + fib(n-2)

print(fib(35))  # 9227465

from typing import Callable, TypeVar
T = TypeVar("T")

def aplicar_dos_veces(f: Callable[[T], T], x: T) -> T:
    return f(f(x))

print(aplicar_dos_veces(lambda x: x + 3, 7))  # 13

def hacer_operacion(operacion):
    """Función de orden superior."""
    def aplicar(a, b):
        return operacion(a, b)
    return aplicar

sumar = hacer_operacion(lambda a, b: a + b)
print(sumar(3, 4))  # 7

def registrar(func):
    """Registra cuántas veces se llama una función."""
    registrar.llamadas = 0
    def wrapper(*args, **kwargs):
        registrar.llamadas += 1
        return func(*args, **kwargs)
    return wrapper

@registrar
def saludar(nombre):
    return f"Hola {nombre}"

saludar("Ana")
saludar("Bob")
print(registrar.llamadas)  # 2

